// Bird field journal: iNaturalist sightings -> OpenAI field-journal plates -> a
// cycling collection on the frame.
//
// Each render:
//  1. Poll iNaturalist (rate-limited by pollMinutes) for birds spotted within
//     radiusKm of the configured spot in the last daysWindow days, and log every
//     species with up to 3 licensed reference photos.
//  2. Plates are drawn one at a time, at most platesPerDay a day: the first
//     straight away, then one every 24/platesPerDay hours, the most-sighted
//     species first. A plate is asked of the OpenAI Responses API in background
//     mode: the render that asks only sends the request, and a later render
//     collects the picture. No render waits a minute for an image, so no
//     render deadline cuts a request off after OpenAI has billed it. Failed
//     attempts count against the day's plates too.
//  3. A collected plate is saved as a JPEG asset straight from the reply
//     (httpRequest's saveBase64Field: the picture never becomes a JS string,
//     which is what makes it fit an 8 MB ESP32) and checked against a
//     reference photo by the model (if verifyPlates), uploaded from that file
//     (bodyAsset).
//  4. Show the next plate in the collection (oldest discovery first) and write a
//     caption line to scene state for a text overlay.
//
// The species log lives in scene state under journalStateKey; declare that key
// as a disk-persisted scene field so the collection survives restarts.

const PAPER_COLOR = "#f5f1e6"
const REFERENCE_PHOTOS_PER_SPECIES = 3
const REFERENCE_PHOTOS_PER_PLATE = 2
const DAY_MS = 86400000
// A background response that has not finished in this long is given up on.
const JOB_GIVE_UP_MS = 30 * 60000

function readJournal(app, key) {
  const stored = app.state[key]
  if (stored && typeof stored === "object" && stored.species) {
    return stored
  }
  return { species: {}, cursor: 0, lastPollAt: 0 }
}

function slugify(name) {
  return String(name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "")
}

function isoDate(millis) {
  return new Date(millis).toISOString().slice(0, 10)
}

function plural(count, word, many) {
  return `${count} ${count === 1 ? word : many || `${word}s`}`
}

function canvasSize(app, context) {
  let width = context.imageWidth || 0
  let height = context.imageHeight || 0
  if (!width || !height) {
    width = app.frame.width
    height = app.frame.height
    if (app.frame.rotate === 90 || app.frame.rotate === 270) {
      const swap = width
      width = height
      height = swap
    }
  }
  return { width, height }
}

function plateSize(app, context) {
  const { width, height } = canvasSize(app, context)
  return height >= width ? "1024x1536" : "1536x1024"
}

function pollSightings(app, journal, lat, lng, now) {
  const cfg = app.config
  const days = Math.max(1, Number(cfg.daysWindow) || 7)
  const d1 = isoDate(now - days * DAY_MS)
  let url = `${cfg.inatHost}/v2/observations` +
    `?taxon_id=${Number(cfg.taxonId) || 3}` +
    `&lat=${lat}&lng=${lng}&radius=${Number(cfg.radiusKm) || 25}` +
    `&d1=${d1}&photos=true` +
    `&photo_license=cc0,cc-by,cc-by-nc,cc-by-sa,cc-by-nc-sa` +
    `&per_page=200&order_by=observed_on&order=desc` +
    `&fields=(observed_on:!t,taxon:(id:!t,name:!t,preferred_common_name:!t),` +
    `photos:(url:!t,license_code:!t,attribution:!t))`
  if (cfg.qualityGrade === "research") {
    url += "&quality_grade=research"
  }

  const res = frameos.httpRequest(url, { timeoutMs: 30000 })
  const ok = res.status === 200
  if (!ok) {
    return { error: res.error || `HTTP ${res.status}` }
  }
  let parsed = null
  try {
    parsed = JSON.parse(res.body)
  } catch (err) {
    return { error: "unparseable response" }
  }
  const results = (parsed && parsed.results) || []

  const seenCounts = {}
  let newSpecies = 0
  for (const obs of results) {
    const taxon = obs.taxon
    if (!taxon || !taxon.id || !taxon.name) {
      continue
    }
    const photos = (obs.photos || []).filter((p) => p && p.url && p.license_code)
    if (!photos.length) {
      continue
    }
    const key = String(taxon.id)
    seenCounts[key] = (seenCounts[key] || 0) + 1
    let entry = journal.species[key]
    if (!entry) {
      entry = {
        taxonId: taxon.id,
        name: taxon.name,
        commonName: taxon.preferred_common_name || taxon.name,
        firstSeen: obs.observed_on || isoDate(now),
        sightings: 0,
        attempts: 0,
        photos: [],
      }
      journal.species[key] = entry
      newSpecies += 1
    }
    if (obs.observed_on && (!entry.lastSeen || obs.observed_on > entry.lastSeen)) {
      entry.lastSeen = obs.observed_on
    }
    for (const photo of photos) {
      if (entry.photos.length >= REFERENCE_PHOTOS_PER_SPECIES) {
        break
      }
      const photoUrl = photo.url.replace("/square.", "/medium.")
      if (!entry.photos.some((p) => p.url === photoUrl)) {
        entry.photos.push({ url: photoUrl, attribution: photo.attribution || "" })
      }
    }
  }
  // Sightings reflect the current window, so counts age out with the window.
  for (const key of Object.keys(seenCounts)) {
    journal.species[key].sightings = seenCounts[key]
  }
  return { newSpecies }
}

function openaiRequest(app, method, path, body, timeoutMs, extra) {
  // extra: httpRequest options of its own (saveBase64Field, bodyAsset).
  const apiKey = frameos.getSetting("openAI", "apiKey") || ""
  const options = Object.assign({
    method,
    headers: { "Authorization": `Bearer ${apiKey}` },
    timeoutMs,
  }, extra || {})
  if (body) {
    options.headers["Content-Type"] = "application/json"
    options.body = JSON.stringify(body)
  }
  const res = frameos.httpRequest(`${app.config.openaiHost}${path}`, options)
  if (res.status !== 200) {
    let message = res.error || `HTTP ${res.status}`
    try {
      message = JSON.parse(res.body).error.message || message
    } catch (err) {}
    return { error: message }
  }
  try {
    return { json: JSON.parse(res.body), saved: res.saved, saveError: res.saveError }
  } catch (err) {
    return { error: "unparseable response" }
  }
}

function extractGeneratedImage(json) {
  for (const item of (json && json.output) || []) {
    if (item.type === "image_generation_call" && item.result) {
      return item.result
    }
  }
  return null
}

function extractOutputText(json) {
  let text = ""
  for (const item of (json && json.output) || []) {
    if (item.type === "message") {
      for (const part of item.content || []) {
        if (part.text) {
          text += part.text
        }
      }
    }
  }
  return text
}

function referenceImages(entry, limit) {
  // iNaturalist's photos are public: OpenAI fetches them itself, so they
  // never pass through the frame's memory.
  return (entry.photos || []).slice(0, limit).map((photo) => ({ type: "input_image", image_url: photo.url }))
}

function platePath(app, entry) {
  return `${app.config.assetFolder || "birdJournal"}/${entry.taxonId}-${slugify(entry.name)}.jpg`
}

function startPlate(app, context, journal, entry, now) {
  // Asks OpenAI for one plate in background mode and returns at once; the job
  // is collected by a later render (collectPlate).
  const cfg = app.config
  const refs = referenceImages(entry, REFERENCE_PHOTOS_PER_PLATE)
  if (!refs.length) {
    entry.attempts += 1
    entry.lastError = "no reference photos"
    return { error: `${entry.commonName}: ${entry.lastError}` }
  }
  const prompt = `${cfg.style}\n\n` +
    `Species: ${entry.commonName} (${entry.name}).\n` +
    `Use the attached reference photo(s) only to get the plumage colors, bill shape, ` +
    `eye color and proportions right; compose an original plate, do not copy a photo.\n` +
    `Letter the labels exactly as "${entry.commonName}" and "${entry.name}".`

  // The attempt is spent the moment it is asked for: OpenAI bills it whatever
  // happens after.
  journal.lastDrawAt = now
  entry.attempts += 1
  frameos.log(`Drawing plate for ${entry.commonName} (${entry.name}), attempt ${entry.attempts}`)
  const result = openaiRequest(app, "POST", "/v1/responses", {
    model: cfg.model,
    background: true,
    input: [{ role: "user", content: [{ type: "input_text", text: prompt }].concat(refs) }],
    tools: [{
      type: "image_generation",
      size: plateSize(app, context),
      quality: cfg.imageQuality || "medium",
      // A JPEG is a tenth of the PNG: it fits an ESP32's memory and storage.
      output_format: "jpeg",
      output_compression: 85,
    }],
    tool_choice: { type: "image_generation" },
  }, 60000)
  if (result.error) {
    entry.lastError = result.error
    return { error: `${entry.commonName}: ${result.error}` }
  }
  journal.job = { taxonId: entry.taxonId, responseId: result.json.id, startedAt: now }
  return {}
}

function verifyPlate(app, entry, path, inlineImage) {
  // { ok, reason } for a verdict, { error } when no verdict came back (the
  // check is asked again on the next render). The plate goes up from its
  // file (bodyAsset), or as the text an older runtime handed the app.
  const marker = "@@FRAMEOS_PLATE@@"
  const prompt = `You are checking a generated field-journal illustration before it joins a birding collection.\n` +
    `Species: ${entry.commonName} (${entry.name}).\n` +
    `The first image is the generated plate; any further images are reference photos of the species.\n` +
    `Reply with strict JSON only: {"ok": true, "reason": "..."} or {"ok": false, "reason": "..."}.\n` +
    `Say ok=true only if the illustrated bird could reasonably be identified as this species ` +
    `(plumage colors, bill shape, overall proportions match the references) and all lettering ` +
    `on the plate is legible and spells the names correctly.`
  const content = [
    { type: "input_text", text: prompt },
    { type: "input_image", image_url: `data:image/jpeg;base64,${inlineImage || marker}` },
  ].concat(referenceImages(entry, 1))
  const result = openaiRequest(app, "POST", "/v1/responses", {
    model: app.config.model,
    input: [{ role: "user", content }],
  }, 60000, inlineImage ? null : { bodyAsset: { marker, path } })
  if (result.error) {
    return { error: result.error }
  }
  const text = extractOutputText(result.json)
  const match = text.match(/\{[\s\S]*\}/)
  if (!match) {
    return { ok: false, reason: "unparseable verdict" }
  }
  try {
    const verdict = JSON.parse(match[0])
    return { ok: verdict.ok === true, reason: verdict.reason || "" }
  } catch (err) {
    return { ok: false, reason: "unparseable verdict" }
  }
}

function storageFull(entry, journal, platesShown) {
  // The frame's storage is full (an ESP32 without a card holds a few
  // plates): draw nothing more until a plate is pruned. The species keeps
  // its attempt.
  delete journal.job
  entry.attempts = Math.max(0, entry.attempts - 1)
  journal.storageFull = { plates: platesShown, at: Date.now() }
  frameos.error(`Could not save the plate for ${entry.commonName}: the frame's storage is full`)
  return { error: "the frame's storage is full, no more plates" }
}

function collectPlate(app, journal, platesShown, now) {
  // Looks in on the plate in the works. Returns { waiting } while OpenAI is
  // still drawing, { error } for a note, {} when the job is settled.
  const cfg = app.config
  const job = journal.job
  const entry = journal.species[String(job.taxonId)]
  if (!entry) {
    delete journal.job
    return {}
  }
  const path = platePath(app, entry)
  // A finished plate goes straight from the reply into its file
  // (saveBase64Field): as a JS string it would not fit an 8 MB ESP32 beside
  // a large canvas. A runtime from before the option hands it over inline.
  const result = openaiRequest(app, "GET", `/v1/responses/${encodeURIComponent(job.responseId)}`, null, 60000,
    { saveBase64Field: { field: "result", path } })
  if (result.error) {
    if (now - job.startedAt > JOB_GIVE_UP_MS) {
      delete journal.job
      entry.lastError = result.error
      return { error: `${entry.commonName}: ${result.error}` }
    }
    return { waiting: true, error: `${entry.commonName}: ${result.error}` }
  }
  const status = result.json.status
  if (status === "queued" || status === "in_progress") {
    if (now - job.startedAt > JOB_GIVE_UP_MS) {
      openaiRequest(app, "POST", `/v1/responses/${encodeURIComponent(job.responseId)}/cancel`, null, 15000)
      delete journal.job
      entry.lastError = "the plate took too long"
      return { error: `${entry.commonName}: ${entry.lastError}` }
    }
    return { waiting: true }
  }
  // A runtime that knows saveBase64Field answers saved or saveError; only
  // one that answers neither hands the picture over inline.
  const inlineImage = result.saved || result.saveError ? null : extractGeneratedImage(result.json)
  if (status !== "completed" || !(result.saved || inlineImage)) {
    if (status === "completed" && result.saveError === "could not write the asset") {
      return storageFull(entry, journal, platesShown)
    }
    delete journal.job
    const reason = (result.json.error && result.json.error.message) || (status === "completed" ? "no image in response" : status)
    entry.lastError = reason
    return { error: `${entry.commonName}: ${reason}` }
  }
  if (inlineImage && !frameos.writeAsset(path, inlineImage)) {
    return storageFull(entry, journal, platesShown)
  }

  if (cfg.verifyPlates) {
    const verdict = verifyPlate(app, entry, path, inlineImage)
    if (verdict.error) {
      // No verdict: the picture stays with OpenAI, ask again next render.
      if (now - job.startedAt > JOB_GIVE_UP_MS) {
        delete journal.job
        frameos.deleteAsset(path)
        entry.lastError = `verification failed: ${verdict.error}`
      }
      return { error: `${entry.commonName}: verification failed: ${verdict.error}` }
    }
    if (!verdict.ok) {
      delete journal.job
      frameos.deleteAsset(path)
      entry.lastError = `verification failed: ${verdict.reason}`
      frameos.log(`Plate for ${entry.commonName} rejected: ${verdict.reason}`)
      return { error: `${entry.commonName}: ${entry.lastError}` }
    }
  }

  delete journal.job
  entry.plate = path
  entry.lastError = ""
  entry.plateDrawnOn = isoDate(now)
  frameos.log(`Added ${entry.commonName} to the journal: ${path}`)
  return {}
}

function pruneCollection(app, journal) {
  const maxSpecies = Math.max(1, Number(app.config.maxSpecies) || 24)
  const entries = Object.values(journal.species)
  if (entries.length <= maxSpecies) {
    return false
  }
  entries.sort((a, b) => String(a.lastSeen || a.firstSeen || "").localeCompare(String(b.lastSeen || b.firstSeen || "")))
  let toRemove = entries.length - maxSpecies
  for (const entry of entries) {
    if (toRemove <= 0) {
      break
    }
    if (journal.job && journal.job.taxonId === entry.taxonId) {
      continue
    }
    if (entry.plate) {
      frameos.deleteAsset(entry.plate)
    }
    delete journal.species[String(entry.taxonId)]
    toRemove -= 1
  }
  return true
}

function formatWait(ms) {
  const minutes = Math.max(1, Math.ceil(ms / 60000))
  if (minutes < 60) {
    return plural(minutes, "minute")
  }
  return plural(Math.round(minutes / 60), "hour")
}

export function get(app, context) {
  const cfg = app.config
  const now = Date.now()
  const journalKey = cfg.journalStateKey || "birdJournal"
  const captionKey = cfg.captionStateKey || "birdCaption"
  const journal = readJournal(app, journalKey)
  const notes = []
  let status = ""

  const lat = parseFloat(cfg.latitude)
  const lng = parseFloat(cfg.longitude)
  const hasCoords = isFinite(lat) && isFinite(lng)

  if (hasCoords) {
    const pollMillis = Math.max(1, Number(cfg.pollMinutes) || 60) * 60000
    if (now - (journal.lastPollAt || 0) >= pollMillis) {
      const poll = pollSightings(app, journal, lat, lng, now)
      if (poll.error) {
        notes.push(`iNaturalist: ${poll.error}`)
        frameos.error(`iNaturalist poll failed: ${poll.error}`)
      } else {
        journal.lastPollAt = now
        if (poll.newSpecies) {
          frameos.log(`Spotted ${plural(poll.newSpecies, "new species", "new species")}`)
        }
      }
      frameos.setState(journalKey, journal)
    }
  } else {
    notes.push("set latitude and longitude to begin")
  }

  if (pruneCollection(app, journal)) {
    frameos.setState(journalKey, journal)
  }

  const platesShown = Object.values(journal.species).filter((e) => e.plate).length
  // Full storage stops the drawing until a plate is pruned, or for a day.
  const full = journal.storageFull
  if (full && (platesShown < full.plates || now - full.at >= DAY_MS)) {
    delete journal.storageFull
  }
  delete journal.storageFullAt
  const storageFull = !!journal.storageFull
  if (storageFull) {
    notes.push("the frame's storage is full, no more plates")
  }
  const hasApiKey = (frameos.getSetting("openAI", "apiKey") || "").length > 0
  let drawing = false

  if (journal.job && hasApiKey) {
    const outcome = collectPlate(app, journal, platesShown, now)
    drawing = !!outcome.waiting
    if (outcome.error) {
      notes.push(outcome.error)
    }
    frameos.setState(journalKey, journal)
  }

  const maxAttempts = Math.max(1, Number(cfg.maxAttempts) || 3)
  const pending = Object.values(journal.species)
    .filter((e) => !e.plate && e.attempts < maxAttempts)
    .sort((a, b) => (b.sightings || 0) - (a.sightings || 0) || String(a.firstSeen || "").localeCompare(String(b.firstSeen || "")))
  const perDay = Number(cfg.platesPerDay)
  const platesPerDay = isFinite(perDay) && cfg.platesPerDay !== "" ? Math.max(0, perDay) : 4
  const nextDrawAt = platesPerDay > 0 ? (journal.lastDrawAt || 0) + DAY_MS / platesPerDay : Infinity

  if (!journal.job && pending.length && hasApiKey && !storageFull) {
    if (now >= nextDrawAt) {
      const outcome = startPlate(app, context, journal, pending[0], now)
      drawing = !outcome.error
      if (outcome.error) {
        notes.push(outcome.error)
      }
      frameos.setState(journalKey, journal)
    } else if (platesPerDay > 0) {
      status = `${plural(pending.length, "species", "species")} to draw, the next in ${formatWait(nextDrawAt - now)}`
    } else {
      status = `${plural(pending.length, "species", "species")} to draw, plates per day is 0`
    }
  } else if (pending.length && !hasApiKey) {
    notes.push(`${plural(pending.length, "plate")} waiting for an OpenAI API key`)
  }

  const plates = Object.values(journal.species)
    .filter((e) => e.plate)
    .sort((a, b) => String(a.firstSeen || "").localeCompare(String(b.firstSeen || "")))

  if (plates.length) {
    const index = (journal.cursor || 0) % plates.length
    journal.cursor = index + 1
    frameos.setState(journalKey, journal)
    const entry = plates[index]
    // No size and no keep: the runtime decodes the plate straight into the
    // canvas it is drawn on. A picture of its own (a size asked for) is a
    // second canvas, 3.8 MB on a 13.3" panel, which an 8 MB ESP32 lacks.
    const image = frameos.loadAssetImage(entry.plate)
    if (image) {
      const days = Math.max(1, Number(cfg.daysWindow) || 7)
      let caption = entry.commonName
      if (entry.name && entry.name !== entry.commonName) {
        caption += ` · ${entry.name}`
      }
      const sightings = entry.sightings || 1
      caption += ` · ${plural(sightings, "sighting")} in ${plural(days, "day")}`
      caption += ` · ${index + 1}/${plates.length}`
      if (notes.length) {
        caption += `\n${notes.join(" · ")}`
      }
      frameos.setState(captionKey, caption)
      return image
    }
    notes.push(`missing plate file for ${entry.commonName}`)
  }

  // Nothing to show yet. While the first plate is being drawn, look again in
  // a minute instead of waiting for the scene's interval.
  if (drawing) {
    frameos.setNextSleep(60)
  }
  const speciesCount = Object.keys(journal.species).length
  let text = "Bird field journal"
  if (drawing) {
    text += ` · ${speciesCount} spotted, drawing the first plate`
  } else if (status) {
    text += ` · ${status}`
  } else if (speciesCount) {
    text += ` · ${speciesCount} spotted`
  } else if (hasCoords) {
    text += ` · waiting for sightings near ${lat.toFixed(2)}, ${lng.toFixed(2)}`
  }
  if (notes.length) {
    text += `\n${notes.join(" · ")}`
  }
  frameos.setState(captionKey, text)
  return frameos.image({ color: PAPER_COLOR })
}

