{
  "name": "Bird field journal (JS)",
  "category": "data",
  "description": "Polls iNaturalist for birds recently spotted near you. Species get field-journal plates drawn by OpenAI from licensed reference photos one at a time, a few a day, each verified for accuracy and saved to the asset collection. Cycles through the collection on each render.",
  "version": "1.1.0",
  "settings": [
    "openAI"
  ],
  "permissions": [
    "assets",
    "assets-write"
  ],
  "fields": [
    {
      "name": "latitude",
      "label": "Latitude",
      "type": "string",
      "value": "",
      "placeholder": "50.85",
      "hint": "Center of the observation circle. Leave empty to pause the journal."
    },
    {
      "name": "longitude",
      "label": "Longitude",
      "type": "string",
      "value": "",
      "placeholder": "4.35"
    },
    {
      "name": "radiusKm",
      "label": "Radius (km)",
      "type": "float",
      "value": "25"
    },
    {
      "name": "daysWindow",
      "label": "Time window (days)",
      "type": "integer",
      "value": "7",
      "hint": "Only sightings observed within this many days count."
    },
    {
      "name": "pollMinutes",
      "label": "Poll every (minutes)",
      "type": "integer",
      "value": "60",
      "hint": "How often to ask iNaturalist for new sightings."
    },
    {
      "name": "platesPerDay",
      "label": "Plates per day",
      "type": "integer",
      "value": "4",
      "hint": "New plates are drawn one at a time, at most this many a day (failed attempts count too). Each is an OpenAI image generation billed to your key. 0 stops drawing."
    },
    {
      "name": "taxonId",
      "label": "iNaturalist taxon ID",
      "type": "integer",
      "value": "3",
      "hint": "3 = birds (Aves). Change for moths, mushrooms, ..."
    },
    {
      "name": "qualityGrade",
      "label": "Observation quality",
      "type": "select",
      "options": [
        "research",
        "any"
      ],
      "value": "research",
      "hint": "research = community-verified IDs only"
    },
    {
      "name": "style",
      "label": "Plate style",
      "type": "text",
      "value": "A 19th-century naturalist's field-journal plate on lightly aged cream paper: fine ink linework with soft watercolor washes. The bird perches on a small branch or stands in typical habitat, anatomically accurate. Around it, small pencil detail studies (head, wing or feather) and short handwritten-style margin notes. Neatly hand-lettered at the bottom: the common name in larger letters and the scientific name in italics beneath it."
    },
    {
      "name": "model",
      "label": "OpenAI model",
      "type": "string",
      "value": "gpt-5.1",
      "hint": "Responses API model that drives image generation and the accuracy check"
    },
    {
      "name": "imageQuality",
      "label": "Plate quality",
      "type": "select",
      "options": [
        "low",
        "medium",
        "high"
      ],
      "value": "medium"
    },
    {
      "name": "verifyPlates",
      "label": "Verify plates",
      "type": "boolean",
      "value": "true",
      "hint": "Have the model double-check each plate against a reference photo before adding it"
    },
    {
