// Plates are drawn one at a time and at most platesPerDay a day: a frame that
// spots 25 species must not ask OpenAI for 25 images in its first hour.

import { get } from './app'

const HOUR = 3600000
const START = Date.UTC(2026, 10, 18, 8, 0, 0)
let clock = START

function species(count: number) {
  const out: Record<string, any> = {}
  for (let i = 1; i <= count; i++) {
    out[String(i)] = {
      taxonId: i,
      name: `Avis ${i}`,
      commonName: `Bird ${i}`,
      firstSeen: '2026-11-17',
      sightings: i,
      attempts: 0,
      photos: [{ url: `https://inat.example/${i}/medium.jpg`, attribution: '' }],
    }
  }
  return out
}

// What OpenAI is asked, and what it has: responses by id, and whether each is done.
let created: any[] = []
let gets: string[] = []
let responses: Record<string, { status: string; image?: string }> = {}
let verdict = { ok: true, reason: 'looks right' }
let written: Record<string, string> = {}
let writeOk = true
// A runtime before saveBase64Field and bodyAsset ignores both.
let oldRuntime = false
let verifyBodies: string[] = []
let loaded: any[] = []

function setup(config: Record<string, any> = {}, state: Record<string, any> = {}) {
  clock = START
  created = []
  gets = []
  responses = {}
  verdict = { ok: true, reason: 'looks right' }
  written = {}
  writeOk = true
  oldRuntime = false
  verifyBodies = []
  Date.now = () => clock
  mock.httpRequest((url: string, options: any = {}) => {
    if (url.startsWith('https://inat.example/')) {
      return { status: 200, bodyBase64: 'UkVG' }
    }
    if (url.startsWith('https://api.inaturalist.org/')) {
      return mock.json({ results: [] })
    }
    if (url === 'https://api.openai.com/v1/responses' && options.method === 'POST') {
      const body = JSON.parse(options.body)
      if (body.tools) {
        created.push(body)
        const id = `resp_${created.length}`
        responses[id] = { status: 'in_progress' }
        return mock.json({ id, status: 'queued', background: true })
      }
      let sent = options.body
      if (options.bodyAsset && !oldRuntime) {
        sent = sent.replace(options.bodyAsset.marker, written[options.bodyAsset.path])
      }
      verifyBodies.push(sent)
      return mock.json({ output: [{ type: 'message', content: [{ type: 'output_text', text: JSON.stringify(verdict) }] }] })
    }
    const match = url.match(/\/v1\/responses\/([^/]+)$/)
    if (match && options.method === 'GET') {
      gets.push(match[1])
      const r = responses[match[1]]
      const save = oldRuntime ? null : options.saveBase64Field
      if (r.image && save) {
        if (!writeOk) {
          return { ...mock.json({ id: match[1], status: r.status, output: [{ type: 'image_generation_call', result: r.image }] }), saveError: 'could not write the asset' }
        }
        written[save.path] = r.image
        const reply = mock.json({ id: match[1], status: r.status, output: [{ type: 'image_generation_call', result: '' }] })
        return { ...reply, saved: { path: save.path, bytes: 3 } }
      }
      const output = r.image ? [{ type: 'image_generation_call', result: r.image }] : []
      return mock.json({ id: match[1], status: r.status, output })
    }
    return mock.response(404, 'nope')
  })
  mock.writeAsset((path: string, base64: string) => {
    if (!writeOk) return false
    written[path] = base64
    return true
  })
  mock.deleteAsset(() => true)
  loaded = []
  mock.loadAssetImage((path: string, options: any) => {
    loaded.push({ path, options })
    return written[path] ? mock.image({ width: 1024, height: 1536 }).image : null
  })
  const app = makeApp({
    // Room for all 25, so none is pruned.
    config: { latitude: '', longitude: '', maxSpecies: 30, ...config },
    state: { birdJournal: { species: species(25), cursor: 0, lastPollAt: 0 }, ...state },
    settings: { openAI: { apiKey: 'sk-test' } },
  })
  return app
}

function render(app: any) {
  clock += 1000
  return get(app, makeContext())
}

function finish(id: string, image = 'SlBFRw==') {
  responses[id] = { status: 'completed', image }
}

const realNow = Date.now

describe('plates, one at a time', () => {
  afterEach(() => {
    Date.now = realNow
  })

  it('asks for one plate in background mode, the most-sighted species first', () => {
    const app = setup()
    render(app)
    expect(created.length).toBe(1)
    expect(created[0].background).toBe(true)
    expect(created[0].tools[0].output_format).toBe('jpeg')
    expect(created[0].input[0].content[0].text).toContain('Bird 25')
    expect(app.state.birdJournal.job.responseId).toBe('resp_1')
    // Nothing to show yet: look again in a minute.
    expect(app.nextSleep).toBe(60)
  })

  it('asks nothing more while the plate is drawn, then saves it', () => {
    const app = setup()
    render(app)
    render(app)
    render(app)
    expect(created.length).toBe(1)
    expect(gets).toEqual(['resp_1', 'resp_1'])
    finish('resp_1')
    render(app)
    expect(Object.keys(written)).toEqual(['birdJournal/25-avis-25.jpg'])
    expect(app.state.birdJournal.job).toBe(undefined)
    expect(app.state.birdJournal.species['25'].plate).toBe('birdJournal/25-avis-25.jpg')
    expect(app.state.birdCaption).toContain('Bird 25')
    expect(created.length).toBe(1)
    // Into the canvas: no size, no keep, so no second picture of its size.
    expect(loaded[loaded.length - 1]).toEqual({ path: 'birdJournal/25-avis-25.jpg', options: undefined })
  })

  it('saves the plate from the reply and verifies it from its file', () => {
    const app = setup()
    render(app)
    // The reference photos go to OpenAI as links: the frame downloads nothing.
    expect(created[0].input[0].content[1]).toEqual({ type: 'input_image', image_url: 'https://inat.example/25/medium.jpg' })
    finish('resp_1', 'UExBVEU=')
    render(app)
    expect(written['birdJournal/25-avis-25.jpg']).toBe('UExBVEU=')
    expect(verifyBodies.length).toBe(1)
    expect(verifyBodies[0]).toContain('data:image/jpeg;base64,UExBVEU=')
  })

  it('on a runtime without saveBase64Field, takes the plate from the reply', () => {
    const app = setup()
    oldRuntime = true
    render(app)
    finish('resp_1', 'T0xE')
    render(app)
    expect(written['birdJournal/25-avis-25.jpg']).toBe('T0xE')
    expect(verifyBodies[0]).toContain('data:image/jpeg;base64,T0xE')
    expect(app.state.birdJournal.species['25'].plate).toBe('birdJournal/25-avis-25.jpg')
  })

  it('deletes a rejected plate', () => {
    const app = setup()
    const deleted: string[] = []
    mock.deleteAsset((path: string) => {
      deleted.push(path)
      return true
    })
    render(app)
    verdict = { ok: false, reason: 'wrong bill' }
    finish('resp_1')
    render(app)
    expect(deleted).toEqual(['birdJournal/25-avis-25.jpg'])
    expect(app.state.birdJournal.species['25'].plate).toBe(undefined)
  })

  it('draws the next plate only when the day allows it', () => {
    const app = setup({ platesPerDay: 4 })
    render(app)
    finish('resp_1')
    clock += 5 * HOUR
    render(app)
    expect(created.length).toBe(1)
    expect(app.state.birdCaption).toContain('Bird 25')
    clock += HOUR
    render(app)
    expect(created.length).toBe(2)
    expect(created[1].input[0].content[0].text).toContain('Bird 24')
  })

  it('a whole day of renders asks for at most platesPerDay plates', () => {
    const app = setup({ platesPerDay: 3 })
    for (let minute = 0; minute < 24 * 60; minute += 5) {
      clock = START + minute * 60000
      for (const id of Object.keys(responses)) finish(id)
      get(app, makeContext())
    }
    expect(created.length).toBe(3)
  })

  it('counts a rejected plate against the day', () => {
    const app = setup({ platesPerDay: 2 })
    render(app)
    verdict = { ok: false, reason: 'wrong bill' }
    finish('resp_1')
    render(app)
    expect(app.state.birdJournal.species['25'].lastError).toContain('wrong bill')
    expect(app.state.birdJournal.species['25'].attempts).toBe(1)
    render(app)
    expect(created.length).toBe(1)
    expect(app.state.birdCaption).toContain('25 species to draw, the next in 12 hours')
  })

  it('draws nothing with platesPerDay 0', () => {
    const app = setup({ platesPerDay: 0 })
    render(app)
    expect(created.length).toBe(0)
    expect(app.state.birdCaption).toContain('plates per day is 0')
  })

  it('stops drawing when the frame cannot store another plate', () => {
    const app = setup({ platesPerDay: 24 })
    writeOk = false
    render(app)
    finish('resp_1')
    render(app)
    expect(app.state.birdJournal.storageFull.plates).toBe(0)
    expect(app.state.birdJournal.species['25'].attempts).toBe(0)
    // The plate never came into JS: the runtime said it could not write it.
    expect(Object.keys(written).length).toBe(0)
    clock += 12 * HOUR
    render(app)
    expect(created.length).toBe(1)
    expect(app.state.birdCaption).toContain('storage is full')
    // A day later it tries again.
    clock += 12 * HOUR
    writeOk = true
    render(app)
    expect(created.length).toBe(2)
    expect(app.state.birdJournal.storageFull).toBe(undefined)
  })

  it('gives up on a plate that never finishes', () => {
    const app = setup()
    render(app)
    clock += 31 * 60000
    render(app)
    expect(app.state.birdJournal.job).toBe(undefined)
    expect(app.state.birdJournal.species['25'].lastError).toBe('the plate took too long')
  })
})
